#include<stdio.h>
#include<stdlib.h>
#include<string.h>
#include<math.h>
#define V 50257
#define M 50000
#define D 768
#define L 12
#define H 12
float*W;long WN;
unsigned char tb[4000000];int to[V],tl[V],np1[M],np2[M];
#define HN 131072
int ht[HN],u2b[512],b2t[256];
unsigned Hh(unsigned char*s,int n){unsigned h=2166136261;for(int i=0;i<n;i++){h^=s[i];h*=16777619;}return h;}
int find(unsigned char*s,int n){unsigned h=Hh(s,n);for(int i=h%HN;;i=(i+1)%HN){if(!ht[i])return-1;int id=ht[i]-1;if(tl[id]==n&&!memcmp(tb+to[id],s,n))return id;}}
void add(int id){unsigned h=Hh(tb+to[id],tl[id]);for(int i=h%HN;;i=(i+1)%HN)if(!ht[i]){ht[i]=id+1;return;}}
void loadbpe(char*fn){int k=0,p=0,t=0;
for(int i=33;i<127;i++){u2b[i]=i;b2t[i]=t;to[t]=p;tb[p++]=i;tl[t]=1;add(t);t++;}
for(int i=161;i<173;i++){u2b[i]=i;b2t[i]=t;to[t]=p;tb[p++]=i;tl[t]=1;add(t);t++;}
for(int i=174;i<256;i++){u2b[i]=i;b2t[i]=t;to[t]=p;tb[p++]=i;tl[t]=1;add(t);t++;}
for(int i=0;i<=32;i++){u2b[256+k]=i;b2t[i]=t;to[t]=p;tb[p++]=i;tl[t]=1;add(t);t++;k++;}
for(int i=127;i<=160;i++){u2b[256+k]=i;b2t[i]=t;to[t]=p;tb[p++]=i;tl[t]=1;add(t);t++;k++;}
u2b[256+k]=173;b2t[173]=t;to[t]=p;tb[p++]=173;tl[t]=1;add(t);
FILE*f=fopen(fn,"rb");unsigned char ln[512];fgets((char*)ln,512,f);
for(int r=0;r<M;r++){fgets((char*)ln,512,f);int sp=0;while(ln[sp]!=' ')sp++;
unsigned char b[64];int n=0;
for(int i=0;i<sp;){int c=ln[i];if(c<128)b[n++]=u2b[c],i++;else{b[n++]=u2b[((c&31)<<6)|(ln[i+1]&63)];i+=2;}}
int id1=find(b,n);n=0;int l2=strlen((char*)ln+sp+1)-1;
for(int i=0;i<l2;){int c=ln[sp+1+i];if(c<128)b[n++]=u2b[c],i++;else{b[n++]=u2b[((c&31)<<6)|(ln[sp+1+i+1]&63)];i+=2;}}
int id2=find(b,n);int id=256+r;to[id]=p;memcpy(tb+p,tb+to[id1],tl[id1]);p+=tl[id1];memcpy(tb+p,tb+to[id2],tl[id2]);p+=tl[id2];tl[id]=p-to[id];add(id);np1[r]=id1;np2[r]=id2;}
fclose(f);}
int tok(char*s,int*tk){int n=0,len=strlen(s);
for(int i=0;i<len;){int st=i;while(i<len&&s[i]==' ')i++;while(i<len&&s[i]!=' ')i++;
int wt[128],wn=0;for(int j=st;j<i;j++)wt[wn++]=b2t[(unsigned char)s[j]];
while(wn>1){int best=-1,bestr=M;for(int a=0;a<wn-1;a++){int r=0;while(r<M&&!(np1[r]==wt[a]&&np2[r]==wt[a+1]))r++;if(r<M&&r<bestr){bestr=r;best=a;}}if(best<0)break;wt[best]=256+bestr;for(int b=best+1;b<wn-1;b++)wt[b]=wt[b+1];wn--;}
for(int j=0;j<wn;j++)tk[n++]=wt[j];}return n;}
void ln(float*o,float*x,float*g,float*b,int ga){float m=0,v=0;for(int i=0;i<D;i++)m+=x[i];m/=D;for(int i=0;i<D;i++){float d=x[i]-m;v+=d*d;}v/=D;float s=1.0f/sqrtf(v+1e-5f);for(int i=0;i<D;i++)o[i]=(x[i]-m)*s*(g[i]+ga)+b[i];}
float ge(float x){return 0.5f*x*(1.0f+erff(x*0.70710678f));}
long NB[12],WTE,WPE,LFG,LFB;
long cb=0,cw=2304,pjb=1771776,pjw=1772544,l1b=2362368,l1g=2363136,l2b=2363904,l2g=2364672,fcb=2365440,fcw=2368512,pcb=4727808,pcw=4728576;
void fwd(int*T,int Tn,int trans,int ga,float*lgs){
static float x[256][D],h[256][D],q[256][D],k[256][D],v[256][D],at[256][D],qk[2304],h1[3072],tm[D];
for(int t=0;t<Tn;t++)for(int i=0;i<D;i++)x[t][i]=W[WTE+T[t]*D+i]+W[WPE+t*D+i];
for(int l=0;l<L;l++){long b=NB[l];
for(int t=0;t<Tn;t++)ln(h[t],x[t],W+b+l1g,W+b+l1b,ga);
for(int t=0;t<Tn;t++){for(int j=0;j<2304;j++){float s=W[b+cb+j];for(int i=0;i<D;i++)s+=h[t][i]*W[b+cw+(trans?j*D+i:i*2304+j)];qk[j]=s;}memcpy(q[t],qk,D*4);memcpy(k[t],qk+D,D*4);memcpy(v[t],qk+2*D,D*4);}
for(int hi=0;hi<H;hi++)for(int t=0;t<Tn;t++){float sc[256];for(int t2=0;t2<=t;t2++){float s=0;for(int d=0;d<64;d++)s+=q[t][hi*64+d]*k[t2][hi*64+d];sc[t2]=s*0.125f;}float mx=sc[0];for(int t2=1;t2<=t;t2++)if(sc[t2]>mx)mx=sc[t2];float sm=0;for(int t2=0;t2<=t;t2++){sc[t2]=expf(sc[t2]-mx);sm+=sc[t2];}for(int t2=0;t2<=t;t2++)sc[t2]/=sm;for(int d=0;d<64;d++){float s=0;for(int t2=0;t2<=t;t2++)s+=sc[t2]*v[t2][hi*64+d];at[t][hi*64+d]=s;}}
for(int t=0;t<Tn;t++){for(int j=0;j<D;j++){float s=W[b+pjb+j];for(int i=0;i<D;i++)s+=at[t][i]*W[b+pjw+(trans?j*D+i:i*D+j)];tm[j]=s;}for(int i=0;i<D;i++)x[t][i]+=tm[i];}
for(int t=0;t<Tn;t++){ln(h[t],x[t],W+b+l2g,W+b+l2b,ga);for(int j=0;j<3072;j++){float s=W[b+fcb+j];for(int i=0;i<D;i++)s+=h[t][i]*W[b+fcw+(trans?j*D+i:i*3072+j)];h1[j]=ge(s);}for(int j=0;j<D;j++){float s=W[b+pcb+j];for(int i=0;i<3072;i++)s+=h1[i]*W[b+pcw+(trans?j*3072+i:i*D+j)];tm[j]=s;}for(int i=0;i<D;i++)x[t][i]+=tm[i];}}
ln(tm,x[Tn-1],W+LFG,W+LFB,ga);for(int i=0;i<V;i++){float s=0;for(int j=0;j<D;j++)s+=tm[j]*W[WTE+i*D+j];lgs[i]=s;}}
int main(int c,char**a){FILE*f=fopen(a[1],"rb");fseek(f,0,SEEK_END);WN=ftell(f)/4;fseek(f,0,SEEK_SET);W=malloc(WN*4);if(fread(W,4,WN,f)!=WN)return 1;fclose(f);loadbpe(a[2]);
long bl[12]={0,7087872,14175744,21263616,28351488,35439360,42527232,49615104,56702976,63790848,70878720,77966592};int bn[12]={0,1,10,11,2,3,4,5,6,7,8,9};for(int i=0;i<12;i++)NB[bn[i]]=bl[i];
WTE=WN-38597376;WPE=WN-38597376-786432;LFG=WN-38597376-786432-768;LFB=WN-38597376-786432-1536;
static float lgs[V];
for(int trans=0;trans<2;trans++)for(int ga=0;ga<2;ga++){
 int p[]={464};fwd(p,1,trans,ga,lgs);
 printf("t%d g%d The:",trans,ga);for(int r=0;r<3;r++){int b=0;for(int i=1;i<V;i++)if(lgs[i]>lgs[b])b=i;printf(" %d(%.1f)",b,lgs[b]);lgs[b]=-1e9;}printf("\n");
 int p2[]={464,2068,7586,21831};fwd(p2,4,trans,ga,lgs);
 printf("t%d g%d fox:",trans,ga);for(int r=0;r<3;r++){int b=0;for(int i=1;i<V;i++)if(lgs[i]>lgs[b])b=i;printf(" %d(%.1f)",b,lgs[b]);lgs[b]=-1e9;}printf("\n");
}
for(int trans=0;trans<2;trans++)for(int ga=0;ga<2;ga++){
 static int tk[256];int T=tok(a[3],tk);
 printf("t%d g%d Gen:",trans,ga);
 for(int i=0;i<20;i++){fwd(tk,T,trans,ga,lgs);int b=0;for(int j=1;j<V;j++)if(lgs[j]>lgs[b])b=j;printf(" %d",b);tk[T++]=b;}
 printf("\n");
}
return 0;}
